lex items-center justify-center gap-1.5 rounded-lg bg-[#075BD6] px-3.5 py-2 xs:px-4.5 font-display text-[0.78rem] sm:text-[0.85rem] font-bold text-white whitespace-nowrap min-h-[38px] shadow-xs transition-all duration-250 hover:bg-[#e53935] hover:shadow-sm group/btn" href="/what-we-do/prison-healthcare/"><span>Learn More</span><svg viewBox="0 0 24 24" aria-hidden="true" class="h-4 w-4 shrink-0 h-3 w-3 shrink-0 transition-transform duration-200 group-hover/btn:translate-x-1" fill="none"><path d="M4 12h15M13 6l6 6-6 6" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"></path></svg></a></div></div></div></div></div></div></section>

<!-- STEP 5: WORKING AREAS (GAZA BAND & MARQUEE) -->
<section class="relative isolate overflow-hidden bg-white py-14 sm:py-16 lg:py-20 border-b border-[#DCE2EA]"><div class="relative"><div class="shell-wide grid gap-10 lg:grid-cols-12 lg:items-end"><div data-visible="false" style="--reveal-delay:0ms" class="reveal  lg:col-span-7"><h2 class="font-display text-[clamp(2.1rem,3.4vw,2.85rem)] leading-[1.1] font-black text-[#0A1020]">The same teams, four thousand kilometres away</h2><p class="mt-4 max-w-2xl text-[1.05rem] leading-relaxed text-[#4B5563] sm:text-[1.12rem]">Our Gaza operation runs on the logic that provides essential healthcare when a health system has stopped functioning. Water before medicine, food before comfort, and a heavy quilt before the cold arrives rather than after it.</p></div><div data-visible="false" style="--reveal-delay:100ms" class="reveal  lg:col-span-5 lg:pl-6"><dl class="grid grid-cols-1 gap-3 rounded-2xl border border-[#DCE2EA] bg-[#F5F7FA] p-4 shadow-xs xs:grid-cols-3"><div class="group rounded-xl p-3 transition-colors duration-200 hover:bg-white"><span class="text-lg" aria-hidden="true">💧</span><dt class="mt-1 font-display text-[1rem] font-bold text-[#075BD6]">Water</dt><dd class="mt-0.5 text-xs sm:text-[0.82rem] font-medium leading-snug text-[#4B5563]">Trucked daily</dd></div><div class="group rounded-xl p-3 transition-colors duration-200 hover:bg-white"><span class="text-lg" aria-hidden="true">🍲</span><dt class="mt-1 font-display text-[1rem] font-bold text-[#075BD6]">Food</dt><dd class="mt-0.5 text-xs sm:text-[0.82rem] font-medium leading-snug text-[#4B5563]">Parcels &amp; hot meals</dd></div><div class="group rounded-xl p-3 transition-colors duration-200 hover:bg-white"><span class="text-lg" aria-hidden="true">🧥</span><dt class="mt-1 font-display text-[1rem] font-bold text-[#075BD6]">Winter</dt><dd class="mt-0.5 text-xs sm:text-[0.82rem] font-medium leading-snug text-[#4B5563]">Quilts &amp; coats</dd></div></dl><div class="mt-6 flex flex-wrap items-center gap-2 sm:gap-4"><a class="grou